"""Lecture-backed CNS teaching records. Model bindings never use fuzzy matching."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parent/'public'
inventory=json.loads((ROOT/'data/structures.json').read_text(encoding='utf8'))
all_meshes=inventory['meshes']
names={m['name'] for m in all_meshes}
def meshes(*bases):
    found=[m['name'] for m in all_meshes if m['base'] in bases]
    for base in bases:assert any(m['base']==base for m in all_meshes),base
    return found
def group(g):return [m['name'] for m in all_meshes if m['group']==g]
S={}
def entry(id,name,targets,page,text,*,bullets=(),view='lateral',mode='surface',note=None,refs=(),aliases=(),kind='anatomical',**extra):
    assert id not in S
    assert targets and set(targets)<=names,(id,set(targets)-names)
    S[id]=dict(id=id,name=name,meshes=targets,page=page,text=text,bullets=list(bullets),view=view,mode=mode,kind=kind,aliases=list(aliases),references=list(refs),**extra)
    if note:S[id]['clarification']=note
    return id

entry('cerebrum','Cerebrum',sum([group(g) for g in ['frontal','parietal','temporal','occipital','opercular','limbic','paracentral']],[]),2,'The cerebral hemispheres form the largest part of the brain.',bullets=['Five lobes in the lecture: frontal, parietal, temporal, occipital and insula.','Three surfaces: superolateral, medial and inferior.'])
entry('brainstem','Brainstem',group('brainstem'),2,'The brainstem is one of the three brain components named in this lecture.',bullets=['Shown in its source position below the cerebrum.','Cerebrum, brainstem and cerebellum together form the brain.'],mode='deep')
entry('cerebellum','Cerebellum',group('cerebellum'),2,'The cerebellum lies behind the brainstem and below the posterior cerebrum.',view='posterior')
entry('spinal-cord','Spinal cord',group('cord'),2,'The spinal cord and brain make up the central nervous system.',mode='cord',view='anterior')
entry('peripheral','Peripheral nerves',group('peripheral'),2,'The PNS includes nerves branching from the brain and spinal cord.',bullets=['Cranial nerves leave the brain; spinal nerves connect with the spinal cord.','The model shows selected actual nerves and spinal roots as examples.'],mode='cord')
entry('grey','Grey matter',meshes('Precentral gyrus','Caudate nucleus','Anterior horn of spinal cord','Posterior horn of spinal cord'),2,'Grey matter consists mainly of neuronal cell bodies.',bullets=['The outer cerebral cortex is grey matter.','A CNS collection of neuronal cell bodies is called a nucleus.'],mode='grey-white',view='medial')
entry('white','White matter',meshes('White matter of telencephalon','White matter of spinal cord'),2,'White matter contains predominantly myelinated axons.',bullets=['Deep cerebral white matter links cortical and subcortical regions.','Association, commissural and projection fibers are studied at the end of the lecture.'],mode='deep',view='medial')
entry('nucleus','Nucleus',meshes('Caudate nucleus'),2,'A nucleus is a collection of neuronal cell bodies within the CNS.',bullets=['The caudate nucleus is shown as a location example, not an additional examinable nucleus list.'],mode='deep',view='anterior')
entry('ganglion','Ganglion',meshes('Spinal ganglion'),2,'A ganglion is a collection of neuronal cell bodies outside the CNS.',bullets=['Compare its position on a spinal nerve with the CNS nucleus.'],mode='cord',view='anterior')
for id,name,text,bullet in [
 ('frontal','Frontal lobe','Anterior to the central sulcus and above the lateral sulcus.','Contains the precentral gyrus and superior, middle and inferior frontal gyri.'),
 ('parietal','Parietal lobe','Posterior to the central sulcus and above the lateral sulcus.','Includes postcentral gyrus, superior parietal lobule and inferior parietal lobule.'),
 ('temporal','Temporal lobe','Below the lateral sulcus.','Identify the superior, middle and inferior temporal gyri.'),
 ('occipital','Occipital lobe','The posterior lobe, related to vision.','Its lateral border is a conventional line, not a single continuous sulcus.')]:
    entry(id,name,group(id),2,text,bullets=[bullet],refs=['ut-lobes'],note='Lobe colors follow the original segmented anatomical parcels. Functional borders are not inferred from these colors.')
entry('insula','Insula · circular boundary',meshes('Circular sulcus of insula'),10,'The insula lies in the depth of the lateral sulcus, under the opercula.',bullets=['The highlighted circular sulcus marks its deep boundary. Surrounding opercula are removed from this view.','Lecture functions: visceral sensation, equilibrium-related input and taste.'],mode='insula',kind='relation',anchor_label='Circular sulcus · insular boundary',refs=['ut-insula'],note='The exported “Insula (Subcentral gyrus and ant. and post. sulci*)” object is a combined surface parcel, not a reliable isolated insular cortex. It is not used as an insular fill. The genuine circular sulcus locates the boundary; no unsegmented insular gyri are invented.')
entry('central','Central sulcus',meshes('Central sulcus'),3,'Separates the frontal and parietal lobes.',bullets=['Precentral gyrus is anterior; postcentral gyrus is posterior.','Rolando is the lecture eponym.'],aliases=['Rolando'],refs=['ut-lobes'])
entry('lateral','Lateral sulcus',meshes('Lat_Fis-post','Lat_Fis-ant-Horizont','Lat_Fis-ant-Vertical'),3,'Separates temporal cortex below from frontal and parietal cortex above.',bullets=['Sylvius is the lecture eponym.','The insula is deeper than the visible lips of this fissure.'],aliases=['Sylvian fissure','Sylvius'],refs=['ut-temporal'])
entry('parieto-occipital','Parieto-occipital sulcus',meshes('Parieto-occipital sulcus'),3,'A key boundary between parietal and occipital cortex on the medial surface.',bullets=['On the lateral surface, the occipital boundary continues as a conventional line to the preoccipital notch.'],view='medial',refs=['ut-lobes'])
entry('precentral','Precentral gyrus · BA 4',meshes('Precentral gyrus'),7,'Primary motor cortex: voluntary motor control of the opposite side of the body.',bullets=['Medial representation: genitalia, hip, leg, foot and toes; ACA supply.','Lateral representation: head, neck, upper limb and face; MCA supply.','A lesion can produce contralateral hemiplegia.'],aliases=['Primary motor cortex','Area 4','Motor strip'])
entry('precentral-sulcus','Precentral sulcus',meshes('Precentral sulcus (inferior part)*','Precentral sulcus (Superior part)*'),3,'Forms the anterior border of the precentral gyrus.',bullets=['The central sulcus forms its posterior border.'])
entry('frontal-sulci','Frontal sulci',meshes('Superior frontal sulcus','Inferior frontal sulcus'),3,'Superior and inferior frontal sulci separate the three frontal gyri.',bullets=['Superior frontal gyrus: above the superior frontal sulcus.','Middle frontal gyrus: between the two sulci.','Inferior frontal gyrus: below the inferior frontal sulcus.'])
entry('superior-frontal','Superior frontal gyrus',meshes('Superior frontal gyrus'),3,'The upper frontal gyrus continues onto the medial surface.',bullets=['Use the medial view to follow its medial frontal continuation.'])
entry('middle-frontal','Middle frontal gyrus',meshes('Middle frontal gyrus'),3,'The middle frontal gyrus lies between the superior and inferior frontal sulci.')
entry('inferior-frontal','Inferior frontal gyrus',meshes('Opercular part of inferior frontal gyrus','Triangular part of inferior frontal gyrus','Orbital part of  inferior frontal gyrus'),8,'Its named parts are pars opercularis, pars triangularis and pars orbitalis.',bullets=['Broca’s classical BA 44/45 territory is associated with the opercular and triangular parts of the dominant hemisphere.'],note='The slide repeats an orbital label. Pars opercularis is the missing third anatomical name; pars orbitalis is not classically part of BA 44/45.',refs=['ut-language'])
entry('broca','Broca’s area · BA 44/45',meshes('Opercular part of inferior frontal gyrus','Triangular part of inferior frontal gyrus'),8,'Motor speech production in the language-dominant hemisphere.',bullets=['Classical lesion pattern: nonfluent, effortful expressive aphasia.','Comprehension is relatively better preserved than speech output.','The left hemisphere is shown as the usual language-dominant example.'],aliases=['Expressive aphasia','Motor speech','Areas 44 45'],refs=['ut-language'],kind='functional',side='left',note='This is a classical regional locator on the opercular/triangular gyri, not a subject-specific cytoarchitectonic BA 44/45 map.')
entry('premotor','Premotor & supplementary cortex · BA 6',meshes('Superior frontal gyrus','Middle frontal gyrus'),8,'Plans, sequences and helps organize movement.',bullets=['Located anterior to primary motor cortex.','Supplementary motor cortex occupies the medial frontal region.'],kind='functional',note='The highlighted gyri are location context. This source has no independent BA 6 segmentation, so their entire outline is not a BA 6 boundary.')
entry('prefrontal','Prefrontal cortex',meshes('Superior frontal gyrus','Middle frontal gyrus','Orbital gyri'),8,'Frontal association cortex supports executive and behavioral functions.',bullets=['Personality and behavior.','Working memory and cognition.','Decision making and motor planning.'],kind='functional',note='Frontal source parcels identify the region; they do not define an exact functional border.')
entry('frontal-eye','Frontal eye field · BA 8',meshes('Middle frontal gyrus','Superior frontal sulcus'),8,'Controls conjugate voluntary eye movements.',bullets=['A destructive unilateral lesion may cause the eyes to deviate toward the lesion.','Locate it in the frontal region anterior to the motor strip.'],aliases=['Eye conjugation','Area 8','Gaze'],kind='functional',refs=['ut-eye'],note='Only a regional locator is available. The source does not contain an exact BA 8 mesh.')
