entry('auditory','Primary auditory cortex · BA 41/42',meshes('Transverse temporal gyri'),10,'Perception and awareness of sound.',bullets=['The transverse temporal gyri lie on the superior temporal surface, hidden inside the lateral fissure.','The lecture describes contralateral sound-stimulus loss.'],mode='auditory',kind='functional',aliases=['Heschl','Hearing','Areas 41 42'],refs=['auditory-reference'],note='Auditory input reaches both hemispheres. A unilateral cortical lesion does not usually produce complete deafness in the opposite ear; severe cortical deafness generally requires bilateral damage.')
entry('auditory-association','Auditory association cortex',meshes('Superior temporal gyrus (Lateral part)','Temporal plane'),10,'Analyzes and recognizes the meaning of sound and perceived words.',mode='auditory',kind='functional',note='The source gyri show location context, not an exact functional parcellation.')
entry('olfactory','Olfactory cortex',meshes('Medial occipitotemporal gyrus (Parahippocampal*)','Hippocampus'),10,'Primary olfactory regions support awareness of smell; association regions support recognition and smell memory.',view='inferior',mode='inferior',kind='functional',refs=['ut-temporal'],note='The source combines parahippocampal anatomy and does not isolate the uncus or an olfactory functional area. Pins identify the related region, not an exact olfactory boundary.')
